/**
 * COMBINED WORDPRESS FRONT-PAGE SCRIPT
 * Includes: Warping Canvas, Letter Shuffle, and Auto-Resizing Stamps
 */

// --- 1. LETTER SHUFFLE MODULE ---
const themePath = "<?php echo get_template_directory_uri(); ?>/assets/images/";
const letters = [
    { el: document.getElementById("letterA"), path: themePath + "svg/A/A_" },
    { el: document.getElementById("letterB"), path: themePath + "svg/B/B_" },
    { el: document.getElementById("letterC"), path: themePath + "svg/C/C_" }
];

async function loadFramesSafely(path) {
    const frames = [];
    let i = 1;
    return new Promise((resolve) => {
        function tryLoad() {
            const img = new Image();
            img.src = `${path}${i}.svg`;
            img.onload = () => { frames.push(img); i++; tryLoad(); };
            img.onerror = () => resolve(frames);
        }
        tryLoad();
    });
}

async function initLetters() {
    await Promise.all(letters.map(async (letter) => {
        letter.frames = await loadFramesSafely(letter.path);
        letter.index = 0;
        if (letter.frames.length > 0) letter.el.src = letter.frames[0].src;
    }));
    startSequentialAnimation();
}

function startSequentialAnimation() {
    let currentLetterIdx = 0;
    const fps = 12;
    const interval = 1000 / fps;
    let lastTime = 0;

    function animate(time) {
        if (time - lastTime >= interval) {
            const letter = letters[currentLetterIdx];
            if (letter && letter.frames && letter.frames.length > 0) {
                letter.index = (letter.index + 1) % letter.frames.length;
                letter.el.src = letter.frames[letter.index].src;
            }
            currentLetterIdx = (currentLetterIdx + 1) % letters.length;
            lastTime = time;
        }
        requestAnimationFrame(animate);
    }
    requestAnimationFrame(animate);
}

// --- 2. WARPING BACKGROUND CANVAS MODULE ---
const warpCanvas = document.getElementById('canvas');
const wCtx = warpCanvas.getContext('2d');
let WIDTH, HEIGHT, mouseX = 0, mouseY = 0;

const WARP_CONFIG = {
    bandHeight: 45,
    stripeWidth: 70,
    stepSize: 26,
    shearX: 480,
    shearY: 240,
    wave: 55,
    minWidth: 230,
    edgeJitter: 17
};

function resizeWarp() {
    WIDTH = window.innerWidth;
    HEIGHT = window.innerHeight;
    warpCanvas.width = WIDTH;
    warpCanvas.height = HEIGHT;
}

function getOffsets(baseY) {
    const normX = (mouseX / WIDTH) * 2 - 1;
    const normY = (mouseY / HEIGHT) * 2 - 1;
    let offsetX = normX * WARP_CONFIG.shearX * (baseY / HEIGHT) + Math.sin(baseY * 0.01) * WARP_CONFIG.wave + (mouseX - WIDTH * 0.5) * 0.1;
    let offsetY = normY * WARP_CONFIG.shearY * ((baseY / HEIGHT) - 0.5) * 2.2 + (mouseY - baseY) * 0.25;
    return {
        offsetX: Math.round(offsetX / WARP_CONFIG.stepSize) * WARP_CONFIG.stepSize,
        offsetY: Math.round(offsetY / WARP_CONFIG.stepSize) * WARP_CONFIG.stepSize
    };
}

function drawWarp() {
    wCtx.clearRect(0, 0, WIDTH, HEIGHT);
    const numBands = Math.ceil(HEIGHT / WARP_CONFIG.bandHeight) + 6;
    for (let i = 0; i < numBands; i++) {
        const baseY = i * WARP_CONFIG.bandHeight - WARP_CONFIG.bandHeight * 0.25;
        const { offsetX, offsetY } = getOffsets(baseY);
        const y = baseY + offsetY;
        if (y > HEIGHT + 100 || y + WARP_CONFIG.bandHeight < -80) continue;
        
        let leftX = 25 + offsetX;
        let width = Math.max(WARP_CONFIG.minWidth, (WIDTH - 70 + ((mouseX / WIDTH) * 2 - 1) * 160)) + Math.sin(baseY * 0.032) * WARP_CONFIG.edgeJitter;
        const period = WARP_CONFIG.stripeWidth * 2;

        for (let x = -period * 4; x < width + period * 4; x += period) {
            const drawX = leftX + x;
            if (drawX + WARP_CONFIG.stripeWidth < 0 || drawX > WIDTH) continue;
            wCtx.fillStyle = '#E8E9E4';
            wCtx.fillRect(Math.floor(drawX), Math.floor(y), WARP_CONFIG.stripeWidth, WARP_CONFIG.bandHeight);
            wCtx.fillStyle = '#6d94ff';
            wCtx.fillRect(Math.floor(drawX + WARP_CONFIG.stripeWidth), Math.floor(y), WARP_CONFIG.stripeWidth, WARP_CONFIG.bandHeight);
        }
    }
    requestAnimationFrame(drawWarp);
}

// --- 3. STAMPS CANVAS MODULE (THE FIX) ---
function initStamps() {
    const pointer = {
        current: 'mouse',
        init() {
            document.addEventListener('pointerdown', (e) => this.current = e.pointerType === 'touch' ? 'touch' : 'mouse');
            if (window.matchMedia?.('(pointer: coarse)').matches) this.current = 'touch';
        },
        isTouch() { return this.current === 'touch'; }
    };
    pointer.init();

    const sCanvas = document.createElement("canvas");
    const sCtx = sCanvas.getContext("2d");
    Object.assign(sCanvas.style, { position: "absolute", top: "0", left: "0", zIndex: "0", pointerEvents: "none" });
    document.body.appendChild(sCanvas);

    const imagesSrc = [themePath + "cursor.svg", themePath + "cursor2.svg", themePath + "cursor3.svg", themePath + "cursor4.svg"];
    const images = [];
    let loadedCount = 0;
    let stamps = [];
    let liveCursor = null;
    let needsNewStamp = false;
    let currentSize = 360, targetSize = 360, ease = 0.15;

    // THE FIX: Robust Height Calculation
    function resizeStamps() {
        const dpr = window.devicePixelRatio || 1;
        const docHeight = Math.max(
            document.body.scrollHeight, 
            document.documentElement.scrollHeight, 
            document.body.offsetHeight
        );
        sCanvas.width = window.innerWidth * dpr;
        sCanvas.height = docHeight * dpr;
        sCanvas.style.width = window.innerWidth + "px";
        sCanvas.style.height = docHeight + "px";
        sCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
    }

    imagesSrc.forEach((src, i) => {
        const img = new Image();
        img.src = src;
        img.onload = () => { if (++loadedCount === imagesSrc.length) start(); };
        images[i] = img;
    });

    function start() {
        resizeStamps();
        if (!pointer.isTouch()) liveCursor = { x: 0, y: 0, index: 0, rotation: 0, size: 360 };
        
        // AUTO-RESIZE OBSERVER: Fixes the "it works after resize" bug
        const ro = new ResizeObserver(() => requestAnimationFrame(resizeStamps));
        ro.observe(document.body);
        window.addEventListener('resize', resizeStamps);
        window.addEventListener('load', resizeStamps);

        animateStamps();
    }

    function animateStamps() {
        sCtx.clearRect(0, 0, sCanvas.width, sCanvas.height);
        if (liveCursor) {
            currentSize += (targetSize - currentSize) * ease;
            liveCursor.size = currentSize;
        }
        stamps.forEach(s => drawImg(s));
        if (liveCursor) drawImg(liveCursor);
        requestAnimationFrame(animateStamps);
    }

    function drawImg(s) {
        const img = images[s.index];
        const aspect = img.width / img.height;
        let w = s.size, h = s.size;
        aspect > 1 ? h = s.size / aspect : w = s.size * aspect;
        sCtx.save();
        sCtx.translate(s.x, s.y);
        sCtx.rotate(s.rotation);
        sCtx.drawImage(img, -w/2, -h/2, w, h);
        sCtx.restore();
    }

    document.addEventListener("pointermove", (e) => {
        if (pointer.isTouch() || !liveCursor) return;
        const x = e.clientX, y = e.clientY + window.scrollY;
        targetSize = e.target.closest('a') ? 100 : 360;
        if (needsNewStamp) {
            liveCursor = { x, y, index: Math.floor(Math.random() * images.length), rotation: Math.random() * Math.PI * 2, size: currentSize };
            needsNewStamp = false;
        } else {
            liveCursor.x = x; liveCursor.y = y;
        }
    });

    document.addEventListener("pointerdown", (e) => {
        const x = e.clientX, y = e.clientY + window.scrollY;
        if (pointer.isTouch()) {
            stamps.push({ x, y, index: Math.floor(Math.random() * images.length), rotation: Math.random() * Math.PI * 2, size: 500 });
        } else if (liveCursor) {
            stamps.push({...liveCursor});
            needsNewStamp = true;
        }
    });
}

// --- INITIALIZE ALL ---
window.addEventListener('load', () => {
    resizeWarp();
    drawWarp();
    initLetters();
    initStamps();
});

window.addEventListener('mousemove', e => { mouseX = e.clientX; mouseY = e.clientY; });
